insert into public.pages (slug, title, kind, blocks, show_in_menu, menu_order) values
 ('home','Home','home','[{"id":"b1","type":"hero","eyebrow":"An archive of river valleys","title":"From the river\nto the household.","body":"Grassroot Archives maps how water distress and community adaptation connect in river valleys, from the headwaters to the household. Each valley gets its own map, stories and transects, and more valleys join as their fieldwork begins.","image":"assets/img/hero.jpg","alt":"A river winding through green monsoon fields and forested hills in Maharashtra","primary_label":"Explore the river valleys →","primary_href":"valley.html","secondary_label":"About the project","secondary_href":"about.html","strip":"From the headwaters to the household","credit":"[Photo credit]"},{"id":"b2","type":"heading","title":"Every valley is read the same way: across transects, down to the household."},{"id":"b3","type":"cards","items":["Transects | | Cross-sections cut at key points along each river, each recording the same six things so places can be compared side by side.","Households | | The household is where river, infrastructure, policy and coping meet, so it is the unit we study across seasons.","The archive | | A public, replicable record of resilience strategies, with printed kits in regional languages free to participating households."]},{"id":"b4","type":"valleys","title":"Explore a valley","body":"New valleys are added from the admin as their maps are ready."},{"id":"b5","type":"chips","title":"Six parameters in every transect","items":["River flows","Water infrastructure","Road infrastructure","Settlements & farms","Industries & businesses","Households"]}]'::jsonb,true,1),
 ('valley','Valley map','valley_template','[{"id":"b17","type":"heading","size":"page","eyebrow":"{valley.region}","title":"{valley.name}"},{"id":"b18","type":"text","body":"{valley.intro}"},{"id":"b19","type":"map"}]'::jsonb,true,2),
 ('river-index','The Archive','index_template','[{"id":"b20","type":"heading","size":"page","eyebrow":"{valley.name} · The Archive","title":"The river, read upstream to downstream"},{"id":"b21","type":"text","body":"A plain catalog of every interview, for researchers and slow connections. No map loads on this page."},{"id":"b22","type":"stories"}]'::jsonb,true,3),
 ('about','About','about','[{"id":"b6","type":"heading","size":"page","eyebrow":"About","title":"Tracing water distress from the river to the household"},{"id":"b7","type":"text","body":"Grassroot Archives documents how water distress and community adaptation connect in river valleys. Every valley is studied with the same method, so valleys can be compared. The Bhima River Valley in Maharashtra is the first; each new valley adds its own map, transects and stories."},{"id":"b8","type":"section","label":"Why river valleys","sublabel":"One river, opposite kinds of distress","body":"Along a single river, water distress can take opposite forms: flooding and urban pressure in some stretches, drought that lasts for years in others. In the Bhima, the first valley in the archive, the river runs from the rain-fed Western Ghats near Bhimashankar, past Pune and Pandharpur, into semi-arid Solapur, then leaves Maharashtra for Karnataka and joins the Krishna.\n\nHouseholds feel this distress, but its causes overlap: rainfall and hydrology, dams and supply schemes, land use, industry, roads and settlements, and policy. Because those links are hard to see, people often blame the weather or distant institutions, and planners rarely see how families cope, or which households sit outside the reach of infrastructure and services."},{"id":"b9","type":"cards","title":"How we work: transects","items":["River flows | 01 | Summer and monsoon flows, mapped with sediment and landform.","Water infrastructure | 02 | The supply and management systems that carry water to people.","Road infrastructure | 03 | Roads and routes that shape access within each transect.","Settlements & farms | 04 | Where people live and farm relative to the river and to services.","Industries & businesses | 05 | Commercial and industrial activity that uses or affects water.","Households | 06 | Case studies in each transect: the unit of analysis."]},{"id":"b10","type":"text","body":"Transects are cross-sections cut at key points along each river. They are case studies, not a statistical sample of the valley. **Map sources:** each valley page credits the elevation data its contour map is drawn from."},{"id":"b11","type":"section","label":"The household as unit","body":"Every system meets at the household. Working up from the home and down from the river, we trace the loops of cause and effect that produce distress, and the coping strategies families have built themselves. We then set those against what infrastructure and policy actually reach. Households are followed across seasons, from rain-fed to drought-prone conditions.","bg":"red"},{"id":"b12","type":"phases","title":"Four phases for each valley","items":["Transects | Phase I · 2 months | Literature review, choosing transects, GIS mapping.","Household unit | Phase II · 6 months | Ethnography, a photographic pilot, documentation.","Causal relationships | Phase III · 2 months | Causal loop and gap analysis.","Patterns | Phase IV · up to 4 months | Findings report, public overview, dialogue with service providers."]},{"id":"b13","type":"cards","title":"What we will produce, and for whom","items":["Outputs | | A transect atlas, a household documentation matrix, causal loop and gap maps, an archive of resilience strategies, and this website, with printed kits in regional languages.","Communities | | Clearer explanations, and strategies already working elsewhere in the valley.","Planners & funders | | Specific gaps and overlaps to act on, and low-cost interventions to target and track at household level."]},{"id":"b14","type":"section","label":"Scope & ethics","body":"Every household takes part only with informed, enthusiastic consent.\n\nEach valley project sets its own boundary. The Bhima study stays within Maharashtra, so language, culture and governance stay comparable; it could extend to Karnataka and the Krishna confluence with further funding.\n\nTributaries are mapped only where a transect crosses them. Findings compare cases; they do not generalise statistically to the whole valley."},{"id":"b15","type":"section","label":"Team","body":"[Team members and roles to be added.]"},{"id":"b16","type":"contact","eyebrow":"Contact","body":"Working in a river valley we document, or want your valley in the archive? Get in touch.","email":"","title":"Write to us"}]'::jsonb,true,4)
